const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/autoupdate";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  const p = path.join(dir, file);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
}
const callsFile = path.join(dir, "calls.jsonl");
write("src/sum.mjs", "export function sum(a, b) {\n  return a + b\n}\n");
write("test/sum.test.mjs", [
  "import { test, expect } from 'vitest'",
  "import { sum } from '../src/sum.mjs'",
  "test('sum', () => { expect(sum(1, 2)).toBe(3) })",
].join("\n") + "\n");
write("vitest.config.mjs", [
  "import { appendFileSync } from 'node:fs'",
  "import { defineConfig } from 'vitest/config'",
  "export default defineConfig({",
  "  test: {",
  "    coverage: {",
  "      enabled: true,",
  "      provider: 'v8',",
  "      include: ['src/**'],",
  "      reporter: ['text'],",
  "      thresholds: {",
  "        lines: 10,",
  "        autoUpdate: (...args) => {",
  "          appendFileSync(" + JSON.stringify(callsFile) + ", JSON.stringify({ count: args.length, newThreshold: args[0], previousThreshold: args[1] === undefined ? 'undefined' : args[1] }) + '\\n')",
  "          return Math.floor(args[0])",
  "        },",
  "      },",
  "    },",
  "  },",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 70000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
if (!fs.existsSync(callsFile)) {
  console.error("ERROR: autoUpdate function was never called (exit " + r.status + ")");
  process.exit(2);
}
const calls = fs.readFileSync(callsFile, "utf8").trim().split("\n").map((l) => JSON.parse(l));
console.log("autoUpdate calls: " + JSON.stringify(calls));
if (calls.length !== 1 || calls[0].newThreshold !== 100) {
  console.error("ERROR: expected one autoUpdate call for lines 100, got " + JSON.stringify(calls));
  process.exit(2);
}
const c = calls[0];
if (c.count === 2 && c.previousThreshold === 10) {
  console.log("PASS: autoUpdate received (100, 10): new and previous threshold");
  process.exit(0);
}
if (c.count === 1 && c.previousThreshold === "undefined") {
  console.error("FAIL: autoUpdate received only the new threshold, no previous threshold");
  process.exit(1);
}
console.error("ERROR: unexpected autoUpdate call " + JSON.stringify(c));
process.exit(2);

